// Run: go run code/main.go

package main

import (
	"fmt"
	"sort"
	"strings"
	"time"
	"unicode"
)

type Span struct {
	Name       string
	Kind       string
	Attributes map[string]string
	Children   []*Span
	StartNs    int64
	EndNs      int64
}

func (s *Span) DurationMs() float64 {
	return float64(s.EndNs-s.StartNs) / 1_000_000
}

type ExternalContentStore struct {
	store   map[string]string
	counter int
}

func NewExternalContentStore() *ExternalContentStore {
	return &ExternalContentStore{store: map[string]string{}}
}

func (c *ExternalContentStore) Put(content string) string {
	c.counter++
	cid := fmt.Sprintf("content_%03d", c.counter)
	c.store[cid] = content
	return cid
}

func (c *ExternalContentStore) Get(cid string) string {
	return c.store[cid]
}

func (c *ExternalContentStore) Items() [][2]string {
	keys := make([]string, 0, len(c.store))
	for k := range c.store {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	out := make([][2]string, len(keys))
	for i, k := range keys {
		out[i] = [2]string{k, c.store[k]}
	}
	return out
}

var clockStart = time.Now()

func perfCounterNs() int64 {
	return int64(time.Since(clockStart))
}

type Tracer struct {
	Root          *Span
	stack         []*Span
	CaptureInline bool
	ContentStore  *ExternalContentStore
}

func NewTracer(captureInline bool, store *ExternalContentStore) *Tracer {
	if store == nil {
		store = NewExternalContentStore()
	}
	root := &Span{Name: "__root__", Kind: "INTERNAL", Attributes: map[string]string{}}
	return &Tracer{Root: root, stack: []*Span{root}, CaptureInline: captureInline, ContentStore: store}
}

func (t *Tracer) StartSpan(name, kind string, attributes map[string]string) *Span {
	attrs := map[string]string{}
	for k, v := range attributes {
		attrs[k] = v
	}
	span := &Span{Name: name, Kind: kind, Attributes: attrs, StartNs: perfCounterNs()}
	parent := t.stack[len(t.stack)-1]
	parent.Children = append(parent.Children, span)
	t.stack = append(t.stack, span)
	return span
}

func (t *Tracer) EndSpan() {
	span := t.stack[len(t.stack)-1]
	t.stack = t.stack[:len(t.stack)-1]
	span.EndNs = perfCounterNs()
}

func (t *Tracer) AddContent(span *Span, key, content string) {
	if t.CaptureInline {
		span.Attributes[key] = truncate(content, 200)
		return
	}
	cid := t.ContentStore.Put(content)
	span.Attributes[key+".reference_id"] = cid
}

func truncate(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return string(r[:n])
	}
	return s
}

func pyRepr(s string) string {
	quote := "'"
	if strings.Contains(s, "'") && !strings.Contains(s, "\"") {
		quote = "\""
	}
	var b strings.Builder
	b.WriteString(quote)
	for _, r := range s {
		switch {
		case r == '\\':
			b.WriteString("\\\\")
		case r == '\n':
			b.WriteString("\\n")
		case r == '\r':
			b.WriteString("\\r")
		case r == '\t':
			b.WriteString("\\t")
		case string(r) == quote:
			b.WriteString("\\" + quote)
		case r < 0x20 || r == 0x7f:
			fmt.Fprintf(&b, "\\x%02x", r)
		case r >= 0x80 && !unicode.IsPrint(r):
			if r <= 0xff {
				fmt.Fprintf(&b, "\\x%02x", r)
			} else if r <= 0xffff {
				fmt.Fprintf(&b, "\\u%04x", r)
			} else {
				fmt.Fprintf(&b, "\\U%08x", r)
			}
		default:
			b.WriteRune(r)
		}
	}
	b.WriteString(quote)
	return b.String()
}

func scriptedLLM(prompt string) string {
	lower := strings.ToLower(prompt)
	if strings.Contains(lower, "search") {
		return "search_tool(\"agent engineering\")"
	}
	if strings.Contains(lower, "result") {
		return "found 3 sources; drafting answer"
	}
	return "final answer: agents in 2026"
}

func searchTool(query string) string {
	return fmt.Sprintf("[3 sources for %s]", pyRepr(query))
}

func render(span *Span, indent int) {
	if span.Name == "__root__" {
		for _, child := range span.Children {
			render(child, indent)
		}
		return
	}
	pad := strings.Repeat("  ", indent)
	dur := "..."
	if span.EndNs != 0 {
		dur = fmt.Sprintf("%.2fms", span.DurationMs())
	}
	fmt.Printf("%s%s  [%s]  %s\n", pad, span.Name, span.Kind, dur)
	keys := make([]string, 0, len(span.Attributes))
	for k := range span.Attributes {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, key := range keys {
		val := span.Attributes[key]
		if len([]rune(val)) > 50 {
			val = truncate(val, 50) + "..."
		}
		fmt.Printf("%s  %s = %s\n", pad, key, pyRepr(val))
	}
	for _, child := range span.Children {
		render(child, indent+1)
	}
}

func main() {
	fmt.Println(strings.Repeat("=", 70))
	fmt.Println("OTEL GENAI SEMANTIC CONVENTIONS: Phase 14, Lesson 23")
	fmt.Println(strings.Repeat("=", 70))

	tracer := NewTracer(false, nil)

	tracer.StartSpan("create_agent research_bot", "INTERNAL", map[string]string{
		"gen_ai.agent.name":     "research_bot",
		"gen_ai.operation.name": "create_agent",
		"gen_ai.provider.name":  "anthropic",
	})
	tracer.EndSpan()

	tracer.StartSpan("invoke_agent research_bot", "INTERNAL", map[string]string{
		"gen_ai.agent.name":     "research_bot",
		"gen_ai.operation.name": "invoke_agent",
		"gen_ai.provider.name":  "anthropic",
		"gen_ai.request.model":  "claude-opus-4-6",
	})

	for turn := 0; turn < 3; turn++ {
		chat := tracer.StartSpan("chat", "INTERNAL", map[string]string{
			"gen_ai.operation.name": "chat",
			"gen_ai.provider.name":  "anthropic",
			"gen_ai.request.model":  "claude-opus-4-6",
			"gen_ai.response.model": "claude-opus-4-6",
		})
		prompt := fmt.Sprintf("turn %d: next action please", turn)
		tracer.AddContent(chat, "gen_ai.input.messages", prompt)
		output := scriptedLLM(prompt)
		tracer.AddContent(chat, "gen_ai.output.messages", output)
		tracer.EndSpan()

		if strings.Contains(output, "search_tool") {
			toolSpan := tracer.StartSpan("tool_call search_tool", "INTERNAL", map[string]string{
				"gen_ai.operation.name": "tool_call",
				"gen_ai.tool.name":      "search_tool",
				"gen_ai.data_source.id": "corpus://mem0/default",
			})
			result := searchTool("agent engineering")
			tracer.AddContent(toolSpan, "gen_ai.tool.result", result)
			tracer.EndSpan()
		}
	}

	tracer.EndSpan()

	fmt.Println("\nspan tree (GenAI-shaped)")
	render(tracer.Root, 0)

	fmt.Println("\nexternal content store (opt-in references, not inline)")
	for _, item := range tracer.ContentStore.Items() {
		fmt.Printf("  %s: %s\n", item[0], truncate(item[1], 60))
	}

	fmt.Println()
	fmt.Println("content NOT captured inline by default. store externally; span")
	fmt.Println("attributes carry reference IDs. set OTEL_SEMCONV_STABILITY_OPT_IN")
	fmt.Println("=gen_ai_latest_experimental to pin experimental attribute names.")
}

"""Stdlib span emitter matching OpenTelemetry GenAI semantic conventions.

Emits invoke_agent INTERNAL spans, per-tool spans, chat spans for LLM calls.
Content capture is opt-in: prompts go to an external store, spans carry IDs.
"""

from __future__ import annotations

import time
from dataclasses import dataclass, field
from typing import Any


@dataclass
class Span:
    name: str
    kind: str = "INTERNAL"
    attributes: dict[str, Any] = field(default_factory=dict)
    children: list["Span"] = field(default_factory=list)
    start_ns: int = 0
    end_ns: int = 0

    @property
    def duration_ms(self) -> float:
        return (self.end_ns - self.start_ns) / 1_000_000


class ExternalContentStore:
    def __init__(self) -> None:
        self._store: dict[str, str] = {}
        self._counter = 0

    def put(self, content: str) -> str:
        self._counter += 1
        cid = f"content_{self._counter:03d}"
        self._store[cid] = content
        return cid

    def get(self, cid: str) -> str:
        return self._store.get(cid, "")

    def items(self) -> list[tuple[str, str]]:
        return sorted(self._store.items())


class Tracer:
    def __init__(self, capture_inline: bool = False,
                 content_store: ExternalContentStore | None = None) -> None:
        self.root = Span(name="__root__")
        self.stack: list[Span] = [self.root]
        self.capture_inline = capture_inline
        self.content_store = content_store or ExternalContentStore()

    def start_span(self, name: str, kind: str = "INTERNAL",
                   attributes: dict[str, Any] | None = None) -> Span:
        span = Span(name=name, kind=kind, attributes=dict(attributes or {}),
                    start_ns=time.perf_counter_ns())
        self.stack[-1].children.append(span)
        self.stack.append(span)
        return span

    def end_span(self) -> None:
        span = self.stack.pop()
        span.end_ns = time.perf_counter_ns()

    def add_content(self, span: Span, key: str, content: str) -> None:
        if self.capture_inline:
            span.attributes[key] = content[:200]
            return
        cid = self.content_store.put(content)
        span.attributes[f"{key}.reference_id"] = cid


def _scripted_llm(prompt: str) -> str:
    if "search" in prompt.lower():
        return "search_tool(\"agent engineering\")"
    if "result" in prompt.lower():
        return "found 3 sources; drafting answer"
    return "final answer: agents in 2026"


def _search_tool(query: str) -> str:
    return f"[3 sources for {query!r}]"


def main() -> None:
    print("=" * 70)
    print("OTEL GENAI SEMANTIC CONVENTIONS: Phase 14, Lesson 23")
    print("=" * 70)

    tracer = Tracer(capture_inline=False)

    create_agent = tracer.start_span(
        "create_agent research_bot",
        attributes={
            "gen_ai.agent.name": "research_bot",
            "gen_ai.operation.name": "create_agent",
            "gen_ai.provider.name": "anthropic",
        },
    )
    tracer.end_span()

    invoke = tracer.start_span(
        "invoke_agent research_bot",
        attributes={
            "gen_ai.agent.name": "research_bot",
            "gen_ai.operation.name": "invoke_agent",
            "gen_ai.provider.name": "anthropic",
            "gen_ai.request.model": "claude-opus-4-6",
        },
    )

    for turn in range(3):
        chat = tracer.start_span(
            "chat",
            attributes={
                "gen_ai.operation.name": "chat",
                "gen_ai.provider.name": "anthropic",
                "gen_ai.request.model": "claude-opus-4-6",
                "gen_ai.response.model": "claude-opus-4-6",
            },
        )
        prompt = f"turn {turn}: next action please"
        tracer.add_content(chat, "gen_ai.input.messages", prompt)
        output = _scripted_llm(prompt)
        tracer.add_content(chat, "gen_ai.output.messages", output)
        tracer.end_span()

        if "search_tool" in output:
            tool_span = tracer.start_span(
                "tool_call search_tool",
                attributes={
                    "gen_ai.operation.name": "tool_call",
                    "gen_ai.tool.name": "search_tool",
                    "gen_ai.data_source.id": "corpus://mem0/default",
                },
            )
            result = _search_tool("agent engineering")
            tracer.add_content(tool_span, "gen_ai.tool.result", result)
            tracer.end_span()

    tracer.end_span()

    def render(span: Span, indent: int = 0) -> None:
        if span.name == "__root__":
            for child in span.children:
                render(child, indent)
            return
        pad = "  " * indent
        dur = f"{span.duration_ms:.2f}ms" if span.end_ns else "..."
        print(f"{pad}{span.name}  [{span.kind}]  {dur}")
        for key in sorted(span.attributes):
            val = span.attributes[key]
            if isinstance(val, str) and len(val) > 50:
                val = val[:50] + "..."
            print(f"{pad}  {key} = {val!r}")
        for child in span.children:
            render(child, indent + 1)

    print("\nspan tree (GenAI-shaped)")
    render(tracer.root)

    print("\nexternal content store (opt-in references, not inline)")
    for cid, content in tracer.content_store.items():
        print(f"  {cid}: {content[:60]}")

    print()
    print("content NOT captured inline by default. store externally; span")
    print("attributes carry reference IDs. set OTEL_SEMCONV_STABILITY_OPT_IN")
    print("=gen_ai_latest_experimental to pin experimental attribute names.")


if __name__ == "__main__":
    main()

// Lesson: OpenTelemetry GenAI Semantic Conventions (phase 14 / lesson 23)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/14-agent-engineering/23-otel-genai-conventions/docs/en.md
// Run: npx tsx phases/14-agent-engineering/23-otel-genai-conventions/code/main.ts

import { hrtime } from "node:process";

function pyStr(s: string): string {
  if (s.includes("'") && !s.includes('"')) return `"${s}"`;
  return `'${s.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
}

function byKey(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

class Span {
  children: Span[] = [];
  endNs = 0n;

  constructor(
    public name: string,
    public kind = "INTERNAL",
    public attributes: Record<string, string> = {},
    public startNs = 0n,
  ) {}

  get durationMs(): number {
    return Number(this.endNs - this.startNs) / 1_000_000;
  }
}

class ExternalContentStore {
  private store = new Map<string, string>();
  private counter = 0;

  put(content: string): string {
    this.counter += 1;
    const cid = `content_${String(this.counter).padStart(3, "0")}`;
    this.store.set(cid, content);
    return cid;
  }

  get(cid: string): string {
    return this.store.get(cid) ?? "";
  }

  items(): [string, string][] {
    return [...this.store.entries()].sort((a, b) => byKey(a[0], b[0]));
  }
}

class Tracer {
  root = new Span("__root__");
  stack: Span[] = [this.root];
  contentStore: ExternalContentStore;

  constructor(
    public captureInline = false,
    contentStore: ExternalContentStore | null = null,
  ) {
    this.contentStore = contentStore ?? new ExternalContentStore();
  }

  startSpan(name: string, kind = "INTERNAL", attributes: Record<string, string> | null = null): Span {
    const span = new Span(name, kind, { ...(attributes ?? {}) }, hrtime.bigint());
    this.stack[this.stack.length - 1]!.children.push(span);
    this.stack.push(span);
    return span;
  }

  endSpan(): void {
    const span = this.stack.pop()!;
    span.endNs = hrtime.bigint();
  }

  addContent(span: Span, key: string, content: string): void {
    if (this.captureInline) {
      span.attributes[key] = content.slice(0, 200);
      return;
    }
    const cid = this.contentStore.put(content);
    span.attributes[`${key}.reference_id`] = cid;
  }
}

function scriptedLlm(prompt: string): string {
  if (prompt.toLowerCase().includes("search")) return 'search_tool("agent engineering")';
  if (prompt.toLowerCase().includes("result")) return "found 3 sources; drafting answer";
  return "final answer: agents in 2026";
}

function searchTool(query: string): string {
  return `[3 sources for ${pyStr(query)}]`;
}

function main(): void {
  console.log("=".repeat(70));
  console.log("OTEL GENAI SEMANTIC CONVENTIONS: Phase 14, Lesson 23");
  console.log("=".repeat(70));

  const tracer = new Tracer(false);

  tracer.startSpan("create_agent research_bot", "INTERNAL", {
    "gen_ai.agent.name": "research_bot",
    "gen_ai.operation.name": "create_agent",
    "gen_ai.provider.name": "anthropic",
  });
  tracer.endSpan();

  tracer.startSpan("invoke_agent research_bot", "INTERNAL", {
    "gen_ai.agent.name": "research_bot",
    "gen_ai.operation.name": "invoke_agent",
    "gen_ai.provider.name": "anthropic",
    "gen_ai.request.model": "claude-opus-4-6",
  });

  for (let turn = 0; turn < 3; turn++) {
    const chat = tracer.startSpan("chat", "INTERNAL", {
      "gen_ai.operation.name": "chat",
      "gen_ai.provider.name": "anthropic",
      "gen_ai.request.model": "claude-opus-4-6",
      "gen_ai.response.model": "claude-opus-4-6",
    });
    const prompt = `turn ${turn}: next action please`;
    tracer.addContent(chat, "gen_ai.input.messages", prompt);
    const output = scriptedLlm(prompt);
    tracer.addContent(chat, "gen_ai.output.messages", output);
    tracer.endSpan();

    if (output.includes("search_tool")) {
      const toolSpan = tracer.startSpan("tool_call search_tool", "INTERNAL", {
        "gen_ai.operation.name": "tool_call",
        "gen_ai.tool.name": "search_tool",
        "gen_ai.data_source.id": "corpus://mem0/default",
      });
      const result = searchTool("agent engineering");
      tracer.addContent(toolSpan, "gen_ai.tool.result", result);
      tracer.endSpan();
    }
  }

  tracer.endSpan();

  const render = (span: Span, indent = 0): void => {
    if (span.name === "__root__") {
      for (const child of span.children) render(child, indent);
      return;
    }
    const pad = "  ".repeat(indent);
    const dur = span.endNs ? `${span.durationMs.toFixed(2)}ms` : "...";
    console.log(`${pad}${span.name}  [${span.kind}]  ${dur}`);
    for (const key of Object.keys(span.attributes).sort(byKey)) {
      let val = span.attributes[key]!;
      if (val.length > 50) val = val.slice(0, 50) + "...";
      console.log(`${pad}  ${key} = ${pyStr(val)}`);
    }
    for (const child of span.children) render(child, indent + 1);
  };

  console.log("\nspan tree (GenAI-shaped)");
  render(tracer.root);

  console.log("\nexternal content store (opt-in references, not inline)");
  for (const [cid, content] of tracer.contentStore.items()) {
    console.log(`  ${cid}: ${content.slice(0, 60)}`);
  }

  console.log();
  console.log("content NOT captured inline by default. store externally; span");
  console.log("attributes carry reference IDs. set OTEL_SEMCONV_STABILITY_OPT_IN");
  console.log("=gen_ai_latest_experimental to pin experimental attribute names.");
}

main();
